-- 0022_yazz_products_strict_drive_text: the Yazz product rows use Lexta's own words, sentence for sentence.
--
-- Why: the strict source sweep (Desmond, 17 November 2026: only the Drive and the current yazzproducts.com, nothing
-- 1773 wrote) changed apps/yazz/content/catalogue.ts so every product line quotes docs/content/yazz/products.md. 0021
-- had written an earlier, partly paraphrased version of the same catalogue into Product Management. This brings the
-- 16 published Yazz rows in line with the catalogue: short and long descriptions, key features, usage and ingredients.
-- Generated from the catalogue, so the two match exactly.
--
-- Only Yazz rows, only these five columns. Rows staff have saved in Product Management are never overwritten
-- ("updated_by is null"). Idempotent. RLS unchanged.
update public.products p
set short_description = v.short_description,
    long_description = v.long_description,
    key_features = v.key_features,
    usage_instructions = v.usage_instructions,
    ingredients = v.ingredients
from public.brands b,
  (values
  ('sanitary-pads', 'Soft flexible wings provide maximum side protection. Ultra-thin.', 'Soft flexible wings provide maximum side protection. Wide adhesive on the back, holds the pad firmly in place. Wider pad for maximum coverage against leakage.', array['Soft flexible wings provide maximum side protection', 'Wide adhesive on the back, holds the pad firmly in place', 'Ultra-thin', 'Convenient & resealable pack, soft dry web cover for natural feeling', 'Round edge gives you comfort', 'Wider pad for maximum coverage against leakage', 'Specially designed wings ensure protection of your panties', '[PLACEHOLDER: confirm current ISO certification and year]', 'The product has passed strict quality inspection']::text[], 'Normal flow: 270mm. Heavy flow: 290mm. Heavy flow: 330mm. In the highly unlikely event of irritation, please discontinue use and share a report to +233 50 996 7400 or via email support@yazzproducts.com. Warning: To avoid danger of suffocation, keep product away from infants and children.', 'Developed with Pearl cotton sheet for your comfort.'),
  ('panty-liners', 'New & Improved thick panty liner. 24 hrs protection.', 'New & Improved thick panty liner. 24 hrs protection.', array['24 hrs protection', 'New & Improved thick panty liner', '180mm; 150mm', '[PLACEHOLDER: confirm current ISO certification and year]', 'The product has passed strict quality inspection']::text[], 'In the highly unlikely event of irritation, please discontinue use and share a report to WhatsApp +233 50 996 7400 or via email support@yazzproducts.com. Warning: To avoid danger of suffocation, keep product away from infants and children.', null),
  ('baby-diapers', 'Elastic waist. Up to 12 hours leakage protection. Cottony soft. Super absorbent.', 'Elastic waist. Up to 12 hours leakage protection. Cottony soft. Super absorbent.', array['Elastic waist', 'Up to 12 hours leakage protection', 'Cottony soft', 'Super absorbent']::text[], 'How to use Yazz baby diaper: 1. Place baby on diaper with the two back tapes at the backside. 2. Attach the two back tapes on the refastenable area to fit your baby. 3. Pull the elastic leg bands towards the side to prevent leakage. 4. Pull up the tape and you can check whether the diaper is wet. Warning: Do not flush. Caution: Wash your hands before changing your baby''s diapers. Make sure your baby is clean and dry before putting on a fresh diaper. Change used diapers to keep the baby comfortable. Always throw away used diapers immediately to avoid bacteria. Plastic bags are dangerous for children and must be kept out of reach or at a safe distance.', null),
  ('baby-pull-up-pants', '360 elastic waist. Up to 12 hours leakage protection.', '360 elastic waist. Up to 12 hours leakage protection. Soft and drying skin climate. Super absorbent.', array['360 elastic waist', 'Up to 12 hours leakage protection', 'Soft and drying skin climate', 'Super absorbent']::text[], 'Caution: Wash your hands before changing your baby''s diapers. Make sure your baby is clean and dry before putting on a fresh diaper. Change used diapers to keep the baby comfortable. Always throw away used diapers immediately to avoid bacteria. Plastic bags are dangerous for children and must be kept out of reach or at a safe distance. How to use Yazz baby diaper: 1. Place baby on diaper with the two back tapes at the backside. 2. Attach the two back tapes on the refastenable area to fit your baby. 3. Pull the elastic leg bands towards the side to prevent leakage. 4. Pull up the tape and you can check whether the diaper is wet. Warning: Do not flush in the WC.', null),
  ('baby-wipes', 'Multi-Purpose cleaning. Alcohol Free.', 'Aloe Vera: Soothe. Hydrate and protect. Super soft for sensitive skin. Care for delicate skin with Aloe Vera-enriched wipes that gently cleanse while helping soothe and hydrate. Castor Oil: Deep Moisture, Soft skin and gentle clean. Gently cleanse while helping lock in moisture with castor oil-enriched wipes, designed to leave skin feeling soft, smooth and comfortably hydrated for everyday use. Lavender: [PLACEHOLDER: Lavender wipes description; Lexta''s text repeats the Aloe Vera copy].', array['Multi-purpose cleaning', 'Alcohol free', 'Leaves skin soft and nourished', 'Gentle, effective cleansing', 'Suitable for everyday use']::text[], 'Keep out of reach of children. Avoid contact with the eye; if this occurs, rinse well with plenty of water. Do not flush down toilet. Dispose of with normal household waste.', 'Lavender: benzalkonium chloride, methylchloroisothiazolinone, methylisothiazolinone, PEG-75 lanolin, fragrance, PEG-40, hydrogenated lavender extract, propylene glycol, water. Castor Oil and Aloe Vera: benzalkonium chloride, methylchloroisothiazolinone, methylisothiazolinone, PEG-75 lanolin, fragrance, PEG-40, hydrogenated castor oil, propylene glycol, water.'),
  ('toothpaste-herbal', 'For natural fresh breath, clean and healthy teeth.', 'For natural fresh breath, clean and healthy teeth. Protection against unpleasant sensations from hot and cold foods and drinks.', array['Helps in reducing the pain of the teeth', 'Helps promote proper hygiene in the mouth, makes the gums strong and prevents cavity formation', 'Helps to reduce all the bad and foul smell from the mouth', 'Gently breaks up stains to get teeth whiter', 'Helps prevent the build up of deposits which can attract stains', 'Helps maintain strong teeth, healthy gums and clean fresh breath']::text[], 'As with other toothpastes, if irritation occurs discontinue use and share a report to WhatsApp +233 50 996 7400 or via email support@yazzproducts.com.', 'Sorbitol, silica, water, sodium lauryl sulfate, sodium carboxymethyl cellulose, flavour, titanium dioxide, sodium saccharin, honeysuckle, sodium fluoride, CI 74260.'),
  ('toothpaste-whitening', 'For a whiter, brighter and healthier smile.', 'For a whiter, brighter and healthier smile. Has a special polishing agent that provides additional stain removal effectively. Polishes off stains that have lodged onto the teeth from foodstuffs. Cool and refreshing mint fragrance makes your mouth smell good at all times.', array['Gently breaks up stains to get teeth whiter', 'Helps prevent the build up of deposits which can attract stains', 'Helps maintain strong teeth, healthy gums and clean fresh breath']::text[], 'As with other toothpastes, if irritation occurs discontinue use and share a report to WhatsApp +233 50 996 7400 or via email support@yazzproducts.com.', 'Calcium carbonate, aqua, sorbitol, glycerin, hydrated silica, sodium lauryl sulfate, sodium carboxymethyl cellulose, hydroxyethylcellulose, flavour, sodium saccharin, calcium phosphate, sodium pyrophosphate, sodium phytate, methylparaben.'),
  ('toothpaste-fluoride', 'Long lasting protection, for brilliant white teeth.', 'Long lasting protection, for brilliant white teeth.', array['Long lasting protection', 'For brilliant white teeth']::text[], 'It is recommended you brush your teeth twice daily with Yazz fluoride toothpaste. As with other toothpastes, if irritation occurs discontinue use and share a report to WhatsApp +233 50 996 7400 or via email support@yazzproducts.com.', 'Sorbitol, aqua, hydrated silica, sodium lauryl sulfate, cellulose gum, aroma, sodium fluoride, sodium benzoate, CI 77891, CI 16255.'),
  ('toothpaste-charcoal', 'Deep clean, removes stain and whitens teeth.', 'With activated charcoal particles, helps to cleanse your mouth and removes deep stains and discolouration. The highly absorbent activated charcoal particles penetrate and draw out stubborn stains, trap colour particles, fight bad breath and whiten teeth enamel.', array['Deep clean', 'Removes stain', 'Whitens teeth', 'Fights bad breath']::text[], 'As with other toothpastes, if irritation occurs discontinue use and share a report to WhatsApp +233 50 996 7400 or via email support@yazzproducts.com.', 'Sorbitol, aqua, hydrated silica, sodium lauryl sulfate, sodium carboxymethyl cellulose, flavour, sodium saccharin, charcoal powder, mica, CI 77266, xanthan gum, methylparaben, sodium fluoride.'),
  ('toothpaste-total-care', 'Everyday protection and care for your teeth.', 'Everyday protection and care for your teeth.', array['Cares for your teeth and refreshes your breath; protects against cavities, foul smell, yellow teeth, plaque, bleeding and swollen gums', 'Helps loosen up gums and teeth, cleans tartar and stains', 'Stimulates gums and provides a pleasantly refreshing taste']::text[], 'As with other toothpastes, if irritation occurs discontinue use and share a report to WhatsApp +233 50 996 7400 or via email support@yazzproducts.com.', 'Sorbitol, aqua, hydrated silica, sodium lauryl sulfate, sodium carboxymethyl cellulose, flavour, sodium saccharin, mica, pigment, triclosan, methylparaben, sodium fluoride.'),
  ('toothbrushes', 'Yazz brushes: Your best smiles.', 'Yazz toothbrushes'' unique bristles are more effective in helping remove plaque and teeth stains. Innovative tongue cleaner designed to gently clean the tongue. Made with a flexible rubber handle specially designed for easy grip and convenient brushing. Dentist recommendation: change your toothbrush at least once every three months.', array['Easy cleaning and massage', 'Removes plaque, protects enamel', 'Gentle on gums, effectively cleans between the teeth']::text[], 'Tips for a healthy smile: Visit the dentist regularly for check-ups. Brush twice a day. Rinse your mouth after every meal. Do not eat sweet sticky food between meals. Change the brush every 3 months. Follow the correct brushing technique: hold the brush with the elbow raised up to shoulder level, and brush in a circular, up and down motion.', null),
  ('washing-powder', 'Yazz Activ detergent with enzymes: removes stubborn stains.', 'The newly improved Yazz Activ detergent with Enzymes has been specially formulated to give you brighter and fresher clothes all the time, free from every stain. Stay bright, fresher and stain-free with Yazz Activ detergent with Enzymes.', array['Detergent with enzymes', 'Removes stubborn stains', 'Brighter and fresher clothes', 'Suitable for cotton, linen, polyester and mixtures of those fabrics']::text[], 'Dissolve Yazz Activ detergent with Enzymes in water and soak clothes for 15 to 20 minutes before washing. For heavy dirt or more clothes, soak for a longer period and use more Yazz Activ detergent accordingly. Wash by quantity of clothes against weight, or against the quantity of Yazz Activ. Check pack for direction at all times. Don''t use for silk or wool clothes. Separate coloured clothes from white and wash them in different basins. Keep the product in a dry place and out of reach of children. In case of eye contact, flush with plenty of water. If swallowed, drink plenty of clean water or milk and seek medical assistance. In case of irritation on skin, discontinue use and seek medical assistance.', 'LAS, phosphate, enzymes, optical brightener, sodium sulphate, SCMC, perfume, sodium carbonate.'),
  ('mama-yazz-jumbo-tissue', 'Big on Care. Made for Family Needs.', 'Meet Mama Yazz®, the jumbo-size tissue option created with busy households in mind. Its larger format offers a practical choice for families and spaces where tissue is used frequently, helping make everyday care more convenient.', array['Jumbo-size format', 'Family-focused convenience', 'Practical for frequent household use']::text[], null, null),
  ('toilet-tissue-individual-wrap', 'A Little Luxury in Everyday Care.', 'Experience everyday comfort with Yazz® Individual Wrap Luxury Toilet Tissue. Conveniently packaged as a single roll, it offers a practical and hygienic solution for personal use, family bathrooms and guest facilities.', array['Individually wrapped', 'Convenient storage', 'Everyday bathroom essential']::text[], null, null),
  ('tissue-napkin', 'Every Sheet, a Touch of Care.', 'From family meals to everyday clean-ups, Yazz® Tissue Napkin offers convenience when you need it. With 150 sheets in a roll, it is a handy addition to dining areas, kitchens and everyday household routines.', array['150 sheets per roll', 'Convenient single-roll format', 'Suitable for everyday household use']::text[], null, null),
  ('individual-tissue', 'Simple Care. Everyday Convenience.', 'Yazz® Individual Tissue brings practical personal hygiene into your daily routine. Its single-roll format makes it an easy choice for home bathrooms, workplaces and other everyday spaces.', array['Single-roll convenience', 'Easy to store', 'Suitable for everyday personal hygiene']::text[], null, null)
  ) as v(slug, short_description, long_description, key_features, usage_instructions, ingredients)
where b.id = p.brand_id and b.slug = 'yazz' and p.slug = v.slug and p.updated_by is null;
